#include <vector>

using namespace std;

class Solution {
public:
    int numOfSubarrays(vector<int>& arr) {
        const int MOD = 1e9 + 7;
        int odd = 0, even = 1, sum = 0, res = 0;

        for (int a : arr) {
            sum += a;
            if (sum % 2)
                res = (res + even) % MOD, ++odd;
            else
                res = (res + odd) % MOD, ++even;
        }
        return res;
    }
};
